  /// Onboarding seviye seçimi: 'A1 · sıfır / temel' vb.
  String onboardingLevelLabel(Cefr level) =>
      '${level.name.toUpperCase()} · ${switch (level) {
        Cefr.a1 => _levelA1,
        Cefr.a2 => _levelA2,
        Cefr.b1 => _levelB1,
        Cefr.b2 => _levelB2,
      }}';

  /// Konuş sekmesindeki seviye başlıkları: 'A1 · Hayatta kalma dili' vb.
  String speakLevelLabel(Cefr level) =>
      '${level.name.toUpperCase()} · ${switch (level) {
        Cefr.a1 => _speakLevelA1,
        Cefr.a2 => _speakLevelA2,
        Cefr.b1 => _speakLevelB1,
        Cefr.b2 => _speakLevelB2,
      }}';

