    PronunciationFeedback.notEnough => _fbNotEnough,
    PronunciationFeedback.excellent => _fbExcellent,
    PronunciationFeedback.good => _fbGood,
    PronunciationFeedback.fair => _fbFair,
    PronunciationFeedback.weak => _fbWeak,
  };

  /// Onboarding plan özeti. Türkçe metin eskisiyle birebir aynıdır.
  String planSummary({
    required Motive motive,
    required String lang,
    required int minutes,
    required String days,
    PracticeTimeOfDay? time,
  }) {
    final goal = switch (motive) {
      Motive.travel => _goalTravel,
      Motive.work => _goalWork,
      Motive.exam => _goalExam,
      Motive.life => _goalLife,
    };
    final timeLabel = time == null
        ? ''
        : switch (time) {
            PracticeTimeOfDay.morning => _planTimeMorning,
            PracticeTimeOfDay.afternoon => _planTimeAfternoon,
            PracticeTimeOfDay.evening => _planTimeEvening,
          };
    final text = _planSummaryText(goal, lang, minutes, days, timeLabel);
    return ui == UiLang.tr ? text : text.replaceAll(' .', '.');
  }

  /// Kayıtlı varsayılan profil adları ('Ana Profil', 'Aile Profili') veri
  /// olarak Türkçe saklanır; ekranda arayüz diline çevrilir. Kullanıcının
  /// kendi verdiği adlar olduğu gibi kalır.
  String profileDisplayName(String name) => switch (name) {
    'Ana Profil' => _mainProfileName,
    'Aile Profili' => _familyProfileDefaultName,
    _ => name,
  };

  /// Sunucudan gelen varsayılan oyuncu adı ('VOXELITH Öğrencisi') ekranda
  /// arayüz diline çevrilir.
  String playerDisplayName(String name) =>
      name == 'VOXELITH Öğrencisi' ? _learnerDefaultName : name;

